  }

  const post: ApiPost = {
    id: numericId,
    title: "'`Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  };

  return NextResponse.json(post);
}

export async function PUT(request: Request, { params }: RouteContext) {
  const { id } = await params;
  const numericId = parsePostId(id);

  if (numericId === null) {
    return NextResponse.json({ error: '"'Invalid post id' }, { status: 400 });
  }

  let body: unknown;

  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
  }

  if ("'!isUpdatePostInput(body)) {
    return NextResponse.json(
      { error: '"'Body must include optional title/content strings' },
      { status: 400 },
    );
  }

  const updatedPost: ApiPost = {
    id: numericId,
    title: body.title ?? "'`Post ${id}`,
    content: body.content ?? `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  };

  return NextResponse.json(updatedPost);
}

