     1	export interface ApiPost {
     2	  id: number;
     3	  title: string;
     4	  content: string;
     5	  createdAt?: string;
     6	  updatedAt?: string;
     7	}
     8	
     9	export interface CreatePostInput {
    10	  title: string;
    11	  content: string;
    12	}
    13	
    14	export interface UpdatePostInput {
    15	  title?: string;
    16	  content?: string;
    17	}
    18	
    19	function isObject(value: unknown): value is Record<string, unknown> {
    20	  return typeof value === 'object' && value !== null;
    21	}
    22	
    23	export function isCreatePostInput(value: unknown): value is CreatePostInput {
    24	  if (!isObject(value)) {
    25	    return false;
    26	  }
    27	
    28	  return (
    29	    typeof value.title === 'string' &&
    30	    value.title.length > 0 &&
    31	    typeof value.content === 'string' &&
    32	    value.content.length > 0
    33	  );
    34	}
    35	
    36	export function isUpdatePostInput(value: unknown): value is UpdatePostInput {
    37	  if (!isObject(value)) {
    38	    return false;
    39	  }
    40	
    41	  const hasTitle =
    42	    !('title' in value) || typeof value.title === 'string' || value.title === undefined;
    43	  const hasContent =
    44	    !('content' in value) ||
    45	    typeof value.content === 'string' ||
    46	    value.content === undefined;
    47	
    48	  return hasTitle && hasContent;
    49	}

